// Lints the Rush pnpm lock file text for the push guard (push-exempt.mjs). An agent may push a
// range that changes common/config/rush/pnpm-lock.yaml only when the new lock passes this lint.
// The lint is the reason a hand edit of the lock cannot smuggle in a tarball, a git source or a
// changed hash: the lock is generated by `rush add` and `rush update`, so a generated lock always
// passes, and a doctored lock does not.
//
// The reader is a line reader for the pnpm lockfile v9 layout, not a YAML parser (the gate scripts
// have no dependencies). It fails closed: a line that it does not know gives a problem.
//
// Rules for the new lock:
//   - The lock starts with `lockfileVersion:`, has LF line ends, and has only the sections
//     `importers`, `packages` and `snapshots` after its header.
//   - Every key of `packages` and `snapshots` is `name@version` with a registry version number
//     (a peer suffix in brackets is allowed). A URL, git, tarball or alias key is a problem. A key
//     in the own scope (`@vprprudhvi/*`) is a problem too: own packages are workspace projects, so
//     the lock never holds them as registry packages (a registry copy would shadow the workspace).
//   - Every `packages` entry has exactly one line `resolution: {integrity: <sha hash>}`. Another
//     resolution (tarball, directory, git, repo, commit) is a problem, and so are the keys that go
//     with those resolutions.
//   - Every `version` in `importers` and every dependency value in `snapshots` is a registry version
//     number, a registry alias (`name@version`, which pnpm writes for `npm:` aliases), or a `link:` to
//     a folder inside the repo (`importers` only). Every `specifier` is a version range, a dist-tag or
//     `workspace:`. A specifier with `:`, `/` or `#` (URL, git, github shorthand, npm alias) is a problem.
//   - A dependency in the own scope (`@vprprudhvi/*`) in `importers` has a `link:` version. A plain
//     version or an alias to an own-scope name is a problem. In `snapshots`, a dependency named in
//     the own scope, or an alias to one, is a problem.
// Rules for new lock against old lock:
//   - The header (settings, overrides, pnpmfileChecksum) is the same.
//   - A package key that is in both locks has the same integrity.
import path from 'node:path';

const SECTIONS = new Set(['importers', 'packages', 'snapshots']);
const VERSION_CORE = /^\d+\.\d+\.\d+$/;
const VERSION_IDENTIFIERS = /^[0-9A-Za-z.-]+$/;
const NAME_PART = /^[A-Za-z0-9][A-Za-z0-9._~-]*$/;
const KEY_LINE = /^ {2}(\S.*?):(?: \{\})?$/;
const DEPENDENCY_NAME_LINE = /^ {6}(\S.*?):$/;
const DEPENDENCY_VALUE_LINE = /^ {6}(\S.*?): (.+)$/;
const IMPORTER_VALUE_LINE = /^ +(specifier|version): (.+)$/;
const RESOLUTION = /^ {4}resolution: \{integrity: (sha(?:1|256|384|512)-[A-Za-z0-9+/]+={0,2})\}$/;
const PACKAGE_BODY_DENIED = /^ {4}(id|tarball|directory|repo|commit|path|type|version|name):/;
const WORKSPACE_SPECIFIER = /^workspace:[A-Za-z0-9^~*.<>=| -]*$/;
const OWN_SCOPE = '@vprprudhvi/';
const LINK_ROOTS = ['projects/', 'packages/', 'platform/', 'tooling/'];
const REPO_STATE_KEYS = new Set([
  'pnpmShrinkwrapHash',
  'preferredVersionsHash',
  'packageJsonInjectedDependenciesHash',
]);
const MAX_PROBLEMS = 20;

/**
 * @typedef {object} ParsedLock
 * @property {string[]} header - The non-blank lines before the first section.
 * @property {Map<string, string | null>} packages - Key of each `packages` entry to its integrity (null when it has none).
 * @property {string[]} problems - What the lint found. Empty for a clean lock.
 */

/**
 * Tells whether a text is a semantic version number (core, optional `-pre-release`, optional `+build`).
 *
 * @param {string} version - The text.
 * @returns {boolean} True for a registry version number.
 */
function isSemver(version) {
  const plus = version.indexOf('+');
  const main = plus === -1 ? version : version.slice(0, plus);
  const dash = main.indexOf('-');
  const core = dash === -1 ? main : main.slice(0, dash);
  return (
    VERSION_CORE.test(core) &&
    (plus === -1 || VERSION_IDENTIFIERS.test(version.slice(plus + 1))) &&
    (dash === -1 || VERSION_IDENTIFIERS.test(main.slice(dash + 1)))
  );
}

/**
 * Tells whether a text is an npm package name, with an optional scope.
 *
 * @param {string} name - The text.
 * @returns {boolean} True for `name` or `@scope/name` made of the characters that npm allows.
 */
function isPackageName(name) {
  if (!name.startsWith('@')) {
    return NAME_PART.test(name);
  }
  const slash = name.indexOf('/');
  return slash > 1 && NAME_PART.test(name.slice(1, slash)) && NAME_PART.test(name.slice(slash + 1));
}

/**
 * Removes one pair of single quotes from a YAML scalar.
 *
 * @param {string} text - The scalar as written.
 * @returns {string | null} The value, or null for a double-quoted or a broken scalar.
 */
function unquote(text) {
  const value = text.trim();
  if (value.startsWith("'")) {
    return value.length >= 2 && value.endsWith("'")
      ? value.slice(1, -1).replaceAll("''", "'")
      : null;
  }
  return value.startsWith('"') ? null : value;
}

/**
 * Checks the key of a `packages` or `snapshots` entry.
 *
 * @param {string} spec - The key without quotes.
 * @returns {string} The problem, or an empty string.
 */
function keyProblem(spec) {
  const base = spec.replace(/\(.*$/, '');
  const at = base.lastIndexOf('@');
  if (at <= 0) {
    return `the key "${spec}" has no version`;
  }
  const name = base.slice(0, at);
  const version = base.slice(at + 1);
  if (name.toLowerCase().startsWith(OWN_SCOPE)) {
    return `the key "${spec}" is an own-scope package, which must be a workspace project`;
  }
  return isPackageName(name) && isSemver(version)
    ? ''
    : `the key "${spec}" is not a registry package (name@version)`;
}

/**
 * Checks a `version` value of `importers` or a dependency value of `snapshots`.
 *
 * @param {string} raw - The value as written.
 * @param {string | null} importer - The importer key, or null inside `snapshots` (a link is not allowed there).
 * @param {string} dependency - The name of the dependency that the value belongs to (empty when unknown).
 * @returns {string} The problem, or an empty string.
 */
function versionProblem(raw, importer, dependency) {
  const value = unquote(raw);
  if (value === null) {
    return `the value ${raw} cannot be read`;
  }
  if (value.startsWith('link:')) {
    if (importer === null) {
      return `the value "${value}" is a link inside snapshots`;
    }
    const linked = value.slice(5);
    const target = path.posix.normalize(path.posix.join('common/temp', importer, linked));
    return !linked.startsWith('/') &&
      !linked.includes('\\') &&
      LINK_ROOTS.some((root) => target.startsWith(root)) &&
      !target.includes('node_modules')
      ? ''
      : `the link "${value}" in importer ${importer} leaves the workspace folders`;
  }
  if (dependency.toLowerCase().startsWith(OWN_SCOPE)) {
    return `the own-scope dependency "${dependency}" has the value "${value}", not a link: to a workspace folder`;
  }
  const plain = value.replace(/\(.*$/, '');
  const alias = plain.lastIndexOf('@');
  if (alias > 0 && plain.toLowerCase().startsWith(OWN_SCOPE)) {
    return `the value "${value}" is an alias to an own-scope package`;
  }
  const aliased =
    alias > 0 && isPackageName(plain.slice(0, alias)) && isSemver(plain.slice(alias + 1));
  return isSemver(plain) || aliased ? '' : `the value "${value}" is not a registry version number`;
}

/**
 * Checks a `specifier` value of `importers`.
 *
 * @param {string} raw - The value as written.
 * @returns {string} The problem, or an empty string.
 */
function specifierProblem(raw) {
  const value = unquote(raw);
  if (value === null) {
    return `the specifier ${raw} cannot be read`;
  }
  if (WORKSPACE_SPECIFIER.test(value)) {
    return '';
  }
  return /[:/#]/.test(value) || value.endsWith('.tgz')
    ? `the specifier "${value}" is a URL, a git source, a tarball or an alias`
    : '';
}

/**
 * @typedef {object} ReaderState
 * @property {string[]} problems - What the lint found so far.
 * @property {string[]} header - The non-blank lines before the first section.
 * @property {Map<string, string | null>} packages - Key of each `packages` entry to its integrity.
 * @property {Set<string>} seenSnapshots - The `snapshots` keys read so far.
 * @property {string} section - The section that the reader is in (empty before the first one).
 * @property {string | null} importer - The importer key that the reader is in.
 * @property {string} dependencyName - The dependency of an importer that the reader is in.
 * @property {string} entry - The key of the `packages` or `snapshots` entry that the reader is in.
 * @property {string} mode - `dependencies` inside a dependency list of a snapshot.
 */

/**
 * Records a problem.
 *
 * @param {ReaderState} state - The reader state.
 * @param {string} where - The line label.
 * @param {string} message - The problem.
 */
function addProblem(state, where, message) {
  state.problems.push(`${where}: ${message}`);
}

/**
 * Splits a line that is not indented into its key and the text after the colon.
 *
 * @param {string} line - The line.
 * @returns {{ key: string, rest: string }} The key (empty when the line is not `key:` or `key: value`) and the trimmed rest.
 */
function splitTopLevel(line) {
  const colon = line.indexOf(':');
  const key = colon === -1 ? '' : line.slice(0, colon);
  const rest = colon === -1 ? '' : line.slice(colon + 1);
  return /^[A-Za-z][A-Za-z0-9]*$/.test(key) && (rest === '' || rest.startsWith(' '))
    ? { key, rest: rest.trim() }
    : { key: '', rest: '' };
}

/**
 * Reads a line that is not indented: a section start, a header line or a key that is not allowed.
 *
 * @param {ReaderState} state - The reader state.
 * @param {string} line - The line.
 * @param {string} where - The line label.
 */
function readTopLevel(state, line, where) {
  const { key, rest } = splitTopLevel(line);
  if (SECTIONS.has(key)) {
    Object.assign(state, { section: key, importer: null, dependencyName: '', entry: '', mode: '' });
    if (rest !== '' && rest !== '{}') {
      addProblem(state, where, `the section ${key} has an unknown value`);
    }
  } else if (state.section === '') {
    state.header.push(line);
  } else {
    addProblem(state, where, `the top-level key "${key}" is not allowed after the header`);
  }
}

/**
 * Checks a `specifier` or `version` line of `importers`.
 *
 * @param {ReaderState} state - The reader state.
 * @param {string} line - The line.
 * @returns {string} The problem, or an empty string.
 */
function importerValueProblem(state, line) {
  const value = IMPORTER_VALUE_LINE.exec(line);
  if (value === null) {
    return '';
  }
  return value[1] === 'version'
    ? versionProblem(value[2] ?? '', state.importer ?? '', state.dependencyName)
    : specifierProblem(value[2] ?? '');
}

/**
 * Reads a line of the `importers` section.
 *
 * @param {ReaderState} state - The reader state.
 * @param {string} line - The line.
 * @param {string} where - The line label.
 */
function readImporterLine(state, line, where) {
  const keyLine = KEY_LINE.exec(line);
  if (keyLine !== null) {
    state.importer = unquote(keyLine[1] ?? '') ?? '';
    state.dependencyName = '';
  }
  const named = DEPENDENCY_NAME_LINE.exec(line);
  if (named !== null) {
    state.dependencyName = unquote(named[1] ?? '') ?? '';
  } else if (/^ {4}\S/.test(line)) {
    state.dependencyName = '';
  }
  const found = importerValueProblem(state, line);
  if (found !== '') {
    addProblem(state, where, found);
  }
}

/**
 * Reads the key line of an entry of `packages` or `snapshots`.
 *
 * @param {ReaderState} state - The reader state.
 * @param {string} line - The line.
 * @param {string} where - The line label.
 */
function readEntryKey(state, line, where) {
  const keyLine = KEY_LINE.exec(line);
  const spec = keyLine === null ? null : unquote(keyLine[1] ?? '');
  const found = spec === null ? 'an entry key that is not readable' : keyProblem(spec);
  state.mode = '';
  if (found !== '' || spec === null) {
    addProblem(state, where, found);
    state.entry = '';
    return;
  }
  state.entry = spec;
  const inPackages = state.section === 'packages';
  if ((inPackages ? state.packages : state.seenSnapshots).has(spec)) {
    addProblem(state, where, `the ${state.section} key "${spec}" is twice in the lock`);
  }
  if (inPackages) {
    state.packages.set(spec, null);
  } else {
    state.seenSnapshots.add(spec);
  }
}

/**
 * Reads a line inside an entry of `packages`: the resolution and the keys that must not be there.
 *
 * @param {ReaderState} state - The reader state.
 * @param {string} line - The line.
 * @param {string} where - The line label.
 */
function readPackageBody(state, line, where) {
  if (state.entry === '') {
    return;
  }
  const resolution = RESOLUTION.exec(line);
  if (resolution !== null) {
    if (state.packages.get(state.entry) !== null) {
      addProblem(state, where, `the package "${state.entry}" has more than one resolution`);
    }
    state.packages.set(state.entry, resolution[1] ?? null);
  } else if (/^ {4}resolution:/.test(line) || PACKAGE_BODY_DENIED.test(line)) {
    addProblem(
      state,
      where,
      `the package "${state.entry}" has a resolution or a key that is not registry-only`,
    );
  }
}

/**
 * Reads a line inside an entry of `snapshots`: the dependency lists.
 *
 * @param {ReaderState} state - The reader state.
 * @param {string} line - The line.
 * @param {string} where - The line label.
 */
function readSnapshotBody(state, line, where) {
  const sub = /^ {4}([A-Za-z]+):/.exec(line);
  if (sub !== null) {
    state.mode =
      sub[1] === 'dependencies' || sub[1] === 'optionalDependencies' ? 'dependencies' : '';
    return;
  }
  const dependency = state.mode === 'dependencies' ? DEPENDENCY_VALUE_LINE.exec(line) : null;
  const found =
    dependency === null
      ? ''
      : versionProblem(dependency[2] ?? '', null, unquote(dependency[1] ?? '') ?? '');
  if (found !== '') {
    addProblem(state, where, found);
  }
}

/**
 * Reads one line of the lock.
 *
 * @param {ReaderState} state - The reader state.
 * @param {string} line - The line.
 * @param {string} where - The line label.
 */
function readLine(state, line, where) {
  if (line.trim() === '') {
    return;
  }
  if (!line.startsWith(' ')) {
    readTopLevel(state, line, where);
  } else if (state.section === '') {
    state.header.push(line);
  } else if (state.section === 'importers') {
    readImporterLine(state, line, where);
  } else if (/^ {2}\S/.test(line)) {
    readEntryKey(state, line, where);
  } else if (state.section === 'packages') {
    readPackageBody(state, line, where);
  } else {
    readSnapshotBody(state, line, where);
  }
}

/**
 * Reads the lock and lints it.
 *
 * @param {string} text - The lock text.
 * @returns {ParsedLock} The header, the `packages` integrity map and the problems.
 */
export function parseLock(text) {
  /** @type {ReaderState} */
  const state = {
    problems: [],
    header: [],
    packages: new Map(),
    seenSnapshots: new Set(),
    section: '',
    importer: null,
    dependencyName: '',
    entry: '',
    mode: '',
  };
  if (text.includes('\r') || text.includes('\0')) {
    state.problems.push('the lock has a carriage return or a null character');
  }
  const lines = text.split('\n');
  if (!(lines[0] ?? '').startsWith('lockfileVersion:')) {
    state.problems.push('the lock does not start with lockfileVersion:');
  }
  for (const [index, line] of lines.entries()) {
    readLine(state, line, `line ${String(index + 1)}`);
  }
  for (const [key, integrity] of state.packages) {
    if (integrity === null) {
      state.problems.push(`the package "${key}" has no resolution with an integrity hash`);
    }
  }
  return {
    header: state.header,
    packages: state.packages,
    problems: state.problems.slice(0, MAX_PROBLEMS),
  };
}

/**
 * Lints a new lock against the old lock.
 *
 * @param {string} before - The lock text of the merge base.
 * @param {string} after - The lock text of the last commit.
 * @returns {string[]} The problems. Empty only when the new lock is clean and keeps the header and the integrity of every package that the old lock has.
 */
export function lockProblems(before, after) {
  const head = parseLock(after);
  const base = parseLock(before);
  const problems = [...head.problems];
  if (base.header.join('\n') !== head.header.join('\n')) {
    problems.push(
      'the lock header (lockfileVersion, settings, overrides, pnpmfileChecksum) changed',
    );
  }
  for (const [key, integrity] of head.packages) {
    const old = base.packages.get(key);
    if (old !== undefined && old !== null && old !== integrity) {
      problems.push(`the integrity of "${key}" changed`);
    }
  }
  return problems.slice(0, MAX_PROBLEMS);
}

/**
 * Checks the text of repo-state.json: only the hash keys that Rush writes, each a hex hash.
 *
 * @param {string} text - The file text (it starts with a `//` comment line).
 * @returns {boolean} True when the file has the expected shape. False on any doubt.
 */
export function repositoryStateIsPlain(text) {
  try {
    const body = text
      .split('\n')
      .filter((line) => !line.trim().startsWith('//'))
      .join('\n');
    const parsed = JSON.parse(body);
    return (
      parsed !== null &&
      typeof parsed === 'object' &&
      !Array.isArray(parsed) &&
      Object.entries(parsed).every(
        ([key, value]) =>
          REPO_STATE_KEYS.has(key) && typeof value === 'string' && /^[0-9a-f]{40,64}$/.test(value),
      )
    );
  } catch {
    return false;
  }
}
